// Korean and Chinese text gets a matching Noto font; Japanese fonts lack Hangul and simplified forms.
const CJK_FONT = { ko: 'Noto Sans KR', 'zh-CN': 'Noto Sans SC', 'zh-TW': 'Noto Sans TC' }[LANG] || '';
export const CJK_FAMILY = CJK_FONT ? `"${CJK_FONT}"` : '';

// Inserts the language's font right after the stack's first family.
export function withCjk(stack) {
  if (!CJK_FAMILY) return stack;
  const i = stack.indexOf(',');
  return i < 0 ? `${stack}, ${CJK_FAMILY}` : `${stack.slice(0, i)}, ${CJK_FAMILY}${stack.slice(i)}`;
}

// ---------- Page ----------

export function applyI18n() {
  const select = document.getElementById('lang');
  if (select) {
    select.innerHTML = LANGS.map((l) => `<option value="${l.id}"${l.id === LANG ? ' selected' : ''}>${l.label}</option>`).join('');
    select.addEventListener('change', () => setLang(select.value));
  }
  if (LANG === 'ja') return;
  document.documentElement.lang = LANG;
  document.querySelector('.logo a')?.setAttribute('href', LANG_INFO.path);
  document.documentElement.classList.add('i18n');
  document.title = t('title');
  if (CJK_FONT) {
    const link = document.createElement('link');
    link.rel = 'stylesheet';
    link.href = `https://fonts.googleapis.com/css2?family=${CJK_FONT.replace(/ /g, '+')}:wght@400;500;700;800&display=swap`;
    document.head.append(link);
    document.documentElement.style.setProperty('--font-cjk', CJK_FAMILY);
  }
  for (const el of document.querySelectorAll('[data-i18n]')) el.textContent = t(el.dataset.i18n);
  for (const el of document.querySelectorAll('[data-i18n-html]')) el.innerHTML = t(el.dataset.i18nHtml);
  for (const el of document.querySelectorAll('[data-i18n-ph]')) el.placeholder = t(el.dataset.i18nPh);
  for (const el of document.querySelectorAll('[data-i18n-title]')) {
    el.title = t(el.dataset.i18nTitle);
    el.setAttribute('aria-label', el.title);
  }
}
